#[derive(Clone, Copy)]
enum LinkEvidence {
    Statistical,
    DonorName,
    ExtractedName,
    TradeUnionFamily,
}
#[derive(Clone, Copy)]
enum EdgeEligibility {
    Link(LinkEvidence),
    Review,
    Reject(PairReason),
}
struct CandidateEdge {
